from google.cloud import translate_v3

def get_translation_client():
    return translate_v3.TranslationServiceClient()

def get_parent_path(project_id, location="global"):
    return f"projects/{project_id}/locations/{location}"

import dataclasses
from typing import List, Dict, Any

@dataclasses.dataclass
class TranslationRequest:
    text: str | List[str]
    source_language: str
    target_language: str
    mime_type: str = "text/plain"

@dataclasses.dataclass
class TranslationResponse:
    translated_text: str | List[str]
    source_language: str
    target_language: str

from translation_client import get_translation_client, get_parent_path
from translation_models import TranslationRequest, TranslationResponse
from typing import List

def batch_translate(payload: TranslationRequest, config: dict = None) -> TranslationResponse:
    config = config or {}
    client = get_translation_client()
    parent = get_parent_path(config['project_id'], config.get('location', 'global'))

    if not isinstance(payload.text, list):
        raise ValueError("payload.text must be a list for batch translation.")

    response = client.translate_text(request={
        "parent": parent,
        "contents": payload.text,
        "mime_type": payload.mime_type,
        "source_language_code": payload.source_language,
        "target_language_code": payload.target_language,
    })

    translated_texts = [translation.translated_text for translation in response.translations]

    return TranslationResponse(
        translated_text=translated_texts,
        source_language=payload.source_language,
        target_language=payload.target_language,
    )

from translation_client import get_translation_client, get_parent_path
from translation_models import TranslationRequest, TranslationResponse

def translate_markup(payload: TranslationRequest, config: dict = None) -> TranslationResponse:
    config = config or {}
    client = get_translation_client()
    parent = get_parent_path(config['project_id'], config.get('location', 'global'))

    if not isinstance(payload.text, str):
        raise ValueError("payload.text must be a string for markup translation.")

    # Ensure mime_type is set to text/html for markup translation
    payload.mime_type = "text/html"

    response = client.translate_text(request={
        "parent": parent,
        "contents": [payload.text],
        "mime_type": payload.mime_type,
        "source_language_code": payload.source_language,
        "target_language_code": payload.target_language,
    })
    return TranslationResponse(
        translated_text=response.translations[0].translated_text,
        source_language=payload.source_language,
        target_language=payload.target_language,
    )

from translation_client import get_translation_client, get_parent_path
from translation_models import TranslationRequest
from typing import Dict, Any

def translate_dictionary_values(payload: Dict[str, str], source_language: str, target_language: str, config: dict = None) -> Dict[str, str]:
    config = config or {}
    client = get_translation_client()
    parent = get_parent_path(config['project_id'], config.get('location', 'global'))

    original_keys = list(payload.keys())
    original_values = [payload[key] for key in original_keys]

    if not original_values:
        return {}

    response = client.translate_text(request={
        "parent": parent,
        "contents": original_values,
        "mime_type": "text/plain",
        "source_language_code": source_language,
        "target_language_code": target_language,
    })

    translated_values = [translation.translated_text for translation in response.translations]

    translated_dict = {}
    for i, key in enumerate(original_keys):
        translated_dict[key] = translated_values[i]

    return translated_dict

from google.cloud import dlp_v2

def check_unsafe_copy(text_content: str, config: dict = None) -> dict:
    config = config or {}
    dlp_client = dlp_v2.DlpServiceClient()

    project_id = config['project_id']
    parent = f"projects/{project_id}/locations/global"

    # Configure the content inspection request
    item = {'value': text_content}

    # Define info types to detect. For "unsafe content", this could be a broad set
    # including profanity, personally identifiable information (PII) if not intended,
    # or other inappropriate content based on custom info types if needed.
    # For simplicity, let's include some common sensitive data types as a proxy for "unsafe" 
    # that might not be suitable for general localized copy.
    info_types = [
        {'name': 'PHONE_NUMBER'},
        {'name': 'EMAIL_ADDRESS'},
        {'name': 'CREDIT_CARD_NUMBER'},
        {'name': 'US_SOCIAL_SECURITY_NUMBER'},
        {'name': 'GENERIC_WORD'} # Can be used with custom dictionaries for profanity/unsafe words
    ]

    # The inspect configuration. You can add custom info types and rules here.
    inspect_config = {
        'info_types': info_types,
        'min_likelihood': dlp_v2.Likelihood.POSSIBLE,
        'limits': {'max_findings_per_request': 0} # 0 means no limit
    }

    response = dlp_client.inspect_content(request={
        'parent': parent,
        'inspect_config': inspect_config,
        'item': item
    })

    unsafe_findings = []
    for finding in response.result.findings:
        unsafe_findings.append({
            'info_type': finding.info_type.name,
            'likelihood': dlp_v2.Likelihood(finding.likelihood).name,
            'quote': finding.quote
        })

    return {
        "text_content": text_content,
        "unsafe_content_detected": bool(unsafe_findings),
        "findings": unsafe_findings
    }
